import { ImageResponse } from "next/og";

// Real PNG icons for Chrome/Android installation; generated by Next.js at no extra cost.
export function GET(request) {
  const dimension = new URL(request.url).searchParams.get("size") === "512" ? 512 : 192;
  const box = Math.round(dimension * 0.72);
  return new ImageResponse(
    <div style={{
      display: "flex", width: "100%", height: "100%", alignItems: "center",
      justifyContent: "center", background: "#171717",
    }}>
      <div style={{
        display: "flex", width: box, height: box,
        borderRadius: Math.round(dimension * 0.13),
        background: "#facc15", color: "#171717",
        alignItems: "center", justifyContent: "center",
        fontSize: Math.round(dimension * 0.27), fontWeight: 900,
      }}>MS</div>
    </div>,
    { width: dimension, height: dimension }
  );
}
